param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
$root=Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict'
function Source([string]$Path){[IO.File]::ReadAllText((Join-Path $root $Path))}
function Body([string]$Source,[string]$Method){Get-AICFMethodBody ([pscustomobject]@{Source=$Source;Code=(ConvertTo-AICFCodeText $Source)}) $Method}
$model=Source 'Vehicles/AICF_VehiclePreset.c'
$slot=Source 'State/AICF_GroupSlot.c'
$trip=Source 'State/Vehicles/AICF_TransportTrip.c'
$acquisition=Source 'Vehicles/AICF_VehicleAcquisitionFlow.c'
$boarding=Source 'Vehicles/AICF_VehicleBoardingFlow.c'
$transit=Source 'Vehicles/AICF_VehicleTransitFlow.c'
$dismount=Source 'Vehicles/AICF_VehicleDismountFlow.c'
$controller=Source 'Vehicles/AICF_TransportTripController.c'
$handoff=Source 'Vehicles/AICF_VehicleTaskHandoff.c'
$tokens=Source 'State/Vehicles/AICF_VehicleBoardingTokens.c'
$service=Source 'UI/AICF_VehiclePresetService.c'
$rpc=Source 'UI/AICF_VehiclePresetRpc.c'
$store=Source 'Vehicles/AICF_VehiclePresetStore.c'
$catalog=Source 'Vehicles/AICF_VehiclePresetCatalog.c'
$editor=Source 'UI/AICF_VehiclePresetEditor.c'
$nativeGate=Source 'Vehicles/AICF_TransportNativeGate.c'
$phaseStates=Source 'State/Vehicles/AICF_VehiclePhaseStates.c'
$checks=0
function Require([bool]$Condition,[string]$Rule){if(!$Condition){throw "FAIL $Rule"};$script:checks++}
$encode=Body $model 'Encode'
Require ($encode -match '"prefab"' -and $encode -match '"seats"' -and $encode -match '"members"') 'STABLE_RECIPE'
Require ($encode -notmatch 'GetID|EntityID|RplId|GetCompartmentMgrID') 'NO_EPHEMERAL_IDENTITY'
Require ($catalog -match '!entry.IsEnabled\(\)' -and $catalog -match 'FindComponent\(VehicleWheeledSimulation\)') 'ENABLED_GROUND_CATALOG'
$append=Body $catalog 'Append'
Require ($catalog -match 'GetFactionByKey\("CIV"\)' -and $catalog -match 'GetEntityCatalogOfType\(EEntityCatalogType.VEHICLE, false\)' -and $append -match 'requireCivilianLabel && !entry.HasEditableEntityLabel\(EEditableEntityLabel.FACTION_CIV\)') 'OWN_AND_NATIVE_CIV_PERMISSION'
Require ($append -match 'FindComponentSource\(resource, VehicleWheeledSimulation\)' -and $append -notmatch 'GetSupplyCost\(\) <= 0') 'ALL_WHEELED_VARIANTS_WITHOUT_SPAWNER_FILTER'
Require ($append -match 'VehicleTrackedSimulation' -and $append -match '/tracked/') 'NATIVE_AND_LEGACY_TRACKED_EXCLUDED'
Require ($append -match 'm_aPrefabs.Contains' -and $append -match 'm_aSources.Insert' -and $append -match 'm_aCategories.Insert') 'DEDUPED_PARALLEL_METADATA'
$price=Body $catalog 'EntryCost'
Require ($price -match 'GetVehiclePresetCostOverride' -and $price -match 'SCR_EntityCatalogSpawnerData' -and $price -match 'm_EntityBudgetCost' -and $price -match 'm_EntityChildrenBudgetCost' -and $price -notmatch 'MergeBudgetCosts\(|AddBudgetValue|SetBudget') 'NATIVE_PRICE_WITHOUT_BUDGET_MUTATION'
$sum=Body $catalog 'ReadCampaignCost'
Require ($sum -match 'EEditableEntityBudget.CAMPAIGN' -and $sum -match 'value < 0' -and $sum -match '2147483646 - total') 'PRICE_RANGE_FAIL_CLOSED'
$selection=Body $editor 'SelectedPrefab'
Require ($selection -match 'm_aVisibleVehicles\[visible\]' -and $selection -match 'm_aPrefabs\[index\]' -and $selection -match 'IsIndexValid') 'FILTERED_INDEX_MAPPING'
$render=Body $editor 'RenderCatalog'
Require ($render -match 'm_aCatalogSources\[index\] != source' -and $render -match 'm_aCatalogCategories\[index\] != category' -and $render -notmatch 'Request\(|SetVehiclePreset|SpawnEntity') 'PRESENTATION_FILTERS_ONLY'
Require ((Body $editor 'OnClick') -match 'SelectedPrefab\(\)' -and (Body $editor 'RevealDraft') -match 'RenderCatalog\(m_Draft.m_sPrefab\)') 'SELECT_AND_LOAD_REVEAL_EXACT_PREFAB'
$closed=Body $editor 'Close'
Require ($closed -match 'ClearCombo\(m_SourceFilter\)' -and $closed -match 'ClearCombo\(m_CategoryFilter\)' -and $closed -match 'm_aVisibleVehicles.Clear' -and $closed -match 'm_mCatalogNameCounts.Clear') 'FILTER_LIFECYCLE_CLEANUP'
$returns=Source 'Forces/AICF_VehicleCrewReturn.c'
$fence=Body $returns 'Current'
foreach($guard in @('m_GroupId','m_iGeneration','m_iAssignment','m_iLoadout','m_iVehicle','m_iSize','m_iExpires','m_aMembers','SafeMember','CountAliveAgents')){Require ($fence.Contains($guard)) "CREW_CONFIRMATION_$guard"}
Require ($service -match 'confirmationId > 0' -and $service -match 'payload == confirmationId.ToString' -and $service -match 'CONFIRM_CREW_REDUCTION' -and $service -match 'CANCEL_CREW') 'EXPLICIT_CREW_CONFIRMATION'
Require ($rpc -match 'operation > AICF_EVehiclePresetOperation.CANCEL_CREW') 'CONFIRM_AND_CANCEL_RPC_RANGE'
$match=Source 'Bootstrap/AICF_MatchController.c'
Require ((Body $match 'CountProjectedManagedAgentsForSpawn') -match 'm_VehicleCrewReturn.CountAgents' -and (Body $match 'CountManagedAgents') -match 'm_VehicleCrewReturn.CountAgents') 'RETURNING_AGENTS_REMAIN_IN_RECRUITMENT_AND_SPAWN_CAP'
$returnTick=Body $returns 'Update'
Require ($returnTick -match 'DistanceSqXZ' -and $returnTick -match 'Quiet' -and $returnTick -match 'SafeBase' -and $returnTick -match 'returning.Current\(\)' -and $returnTick -match 'DespawnMembers' -and $returns -notmatch 'SetOrigin|SetWorldTransform|CallLater') 'PHYSICAL_RETURN_WITHOUT_TELEPORT_OR_TIMEOUT_DELETE'
Require ((Body $slot 'CommitVehicleCrew') -match 'GetLoadout\(index\)' -and $slot -match 'GetEquipmentSourceIndex' -and $slot -match 'AICF_RebindMemberPositions') 'SELECTED_KIT_AND_ROSTER_COMPACTION'
Require ((Body $slot 'RecordRecruitedMember') -match 'm_aEquipmentSourceIndices\[index\] = index' -and (Body $match 'ResolveLoadoutContext') -match 'slot.GetEquipmentSourceIndex\(member\)') 'LIVE_ROLE_INSPECTOR_AND_NEW_RECRUIT_ROLE_RESET'
Require ($closed -match 'm_Preview.Clear' -and (Body $editor 'RefreshPreview') -match 'BuildVehicle' -and $editor -match 'preserveDraft' -and $editor -match 'sameGeneration') 'PREVIEW_AND_AUTOMATIC_DRAFT_LIFECYCLE'
$key=Body $model 'SeatKey'
Require ($key -match 'RelativeOwnerIndex' -and $key -notmatch 'GetCompartmentMgrID') 'INSTANCE_INDEPENDENT_SEAT'
$validation=Body $model 'ValidateRoster'
foreach($guard in @('MatchesSeats','GetDesiredSize','MEMBER_INACTIVE','MANDATORY_CREW_MISSING','MEMBER_WITHOUT_SEAT','CountAliveAgents','IsAuthoritativeAIEntity')){Require ($validation.Contains($guard)) "ROSTER_$guard"}
$binding=Body $slot 'SetVehiclePreset'
Require ($binding -match 'Replication.IsServer' -and $binding -match 'expectedRevision != m_iVehiclePresetRevision' -and $binding -match 'SameAssignment') 'AUTHORITY_REVISION_IDEMPOTENCE'
Require ($binding -notmatch 'SetDesiredSize|SetLoadout|SpawnEntity|AddSupplies') 'NO_PARTIAL_ROSTER_KIT_SPAWN'
$current=Body $trip 'IsVehiclePresetCurrent'
foreach($guard in @('GetVehiclePresetRevision','GetSpawnGeneration','GetGroup','VehiclePresetMember','IsAuthoritativeAIEntity','GetRosterMember')){Require ($current.Contains($guard)) "IDENTITY_$guard"}
$candidates=Body $acquisition 'ResolveTripCandidates'
Require ($candidates -match 'candidates.Clear\(\)' -and $candidates -match 'candidates.Insert\(preset.m_sPrefab\)' -and $candidates -match 'ValidateRoster') 'EXACT_PREFAB_NO_FALLBACK'
$begin=Body $boarding 'BeginPreset'
$tick=Body $boarding 'TickPreset'
Require ($begin -match 'SCR_AIGetInVehicle' -and $begin -match 'TrackToken' -and $begin -match 'CreateFence') 'OWNED_NATIVE_ACTIONS'
Require ($tick -match 'GetOccupant\(\)' -and $tick -match 'access.GetCompartment\(\) == seats\[i\]' -and $tick -match 'ObserveSettled' -and $tick -match 'StartMovement') 'PHYSICAL_OCCUPANTS_BEFORE_TRANSIT'
Require ($begin -notmatch 'CommitTransition|SpawnEntity|DeleteRplEntity|\.GetInVehicle\(') 'BOARDING_FLOW_BOUNDARY'
$retry=Body $boarding 'TryRetryPresetSeat'
Require ($retry -match 'IsVehiclePresetCurrent' -and $retry -match 'token.Matches\(trip, lease, group\)' -and $retry -match 'IsPhysicalMutationOwnerSafe' -and $retry -match 'token.GetCompartment\(\) != seat') 'PRESET_RETRY_EXACT_IDENTITY'
Require ($retry -match 'GetRetryCount\(\) >= 2' -and $retry -match 'GetProgressAgeMs\(\) < 12000' -and $retry -match 'state.GetAbsoluteDeadlineMs\(\)' -and $retry -notmatch 'state.Begin\(') 'PRESET_RETRY_BOUNDED_NO_DEADLINE_RESET'
Require ($retry -match 'access.IsInCompartment\(\)' -and $retry -match 'access.IsGettingIn\(\)' -and $retry -match 'access.IsGettingOut\(\)' -and $retry -match 'seat.IsReserved\(\) && !seat.IsReservedBy\(member\)' -and $retry -notmatch '\.GetInVehicle\(|SetOrigin|EGetInType.TELEPORT') 'PRESET_RETRY_PRESERVES_TRANSITIONS_AND_FOREIGN_SEATS'
Require ($retry -match 'token.CancelOwnerSafe\(\)' -and $retry -match 'RemoveActionFence\(token.GetFence\(\)\)' -and $retry -match 'TrackToken\(state, replacement\)' -and $retry -match 'CreateFence') 'PRESET_RETRY_OWNED_CLEANUP_AND_FRESH_FENCE'
Require ($tick -match 'bool pendingSeat' -and $tick -match 'if \(!pendingSeat\)' -and $tick -match 'token.WasPresetQueued\(\)' -and $begin -match 'QueuePresetSeat') 'PRESET_SERIAL_ACTIONS_KEEP_ALL_EXACT_RESERVATIONS'
Require ($begin -match 'Math.Max\(3, requiredSeats\)' -and $begin -match 'Math.Min\(trip.GetAbsoluteDeadlineMs\(\), now \+ plannedTimeoutMs\)' -and $tick -notmatch 'state.Begin\(') 'SERIAL_BUDGET_SCALES_WITH_ASSIGNED_CREW_AND_NEVER_REARMS'
Require ((Body $handoff 'RestoreInfantryOrder') -match 'alive == 1 && slot.GetDesiredSize\(\) > 1' -and (Body $handoff 'RestoreInfantryOrder') -match 'slot.GetDesiredSize\(\) > 1 &&\s*AICF_GroupRuntime.CountAliveAgents') 'INTENTIONAL_SOLO_CONTINUES_ORDER_SURVIVOR_STILL_RETREATS'
$complete=Body $tokens 'CompleteSettledPresetAction'
Require ($complete -match 'IsPhysicalMutationOwnerSafe' -and $complete -match 'IsTrackedActionOwnedByUtility' -and $complete -match 'GetOccupant\(\) != m_ReservedEntity' -and $complete -match 'GetCompartment\(\) != m_Compartment' -and $complete -match 'access.IsGettingIn\(\)' -and $complete -match 'access.IsGettingOut\(\)') 'NATIVE_COMPLETION_REQUIRES_OWNED_EXACT_SETTLED_ACTOR'
Require ($complete -match 'm_GetInAction.Complete\(\)' -and $complete -notmatch '\.Fail\(|GetOutVehicle|SetOrigin' -and $tick -match 'CompleteSettledPresetAction') 'NATIVE_COMPLETION_CANNOT_EJECT_SEATED_CREW'
$gateTick=Body $transit 'Tick'
Require ($gateTick.IndexOf('ObserveNativeGate') -lt $gateTick.IndexOf('ProcessMandatoryCrew') -and $gateTick.IndexOf('IsDeadlineReached') -lt $gateTick.IndexOf('ObserveNativeGate')) 'NATIVE_GATE_BEFORE_CREW_RECOVERY_AFTER_ABSOLUTE_DEADLINE'
Require ($nativeGate -match 'PRIORITY_BEHAVIOR_OPEN_NAVLINK_DOOR' -and $nativeGate -match 'SMART_ACTION_TAG' -and $nativeGate -match 'returnAction' -and $nativeGate -match 'exitAction' -and $nativeGate -match 'GetRelatedGroupActivity\(\) != activity') 'NATIVE_GATE_REQUIRES_PROVEN_PAIRED_CHAIN'
Require ($nativeGate -match 'm_Vehicle.GetID\(\) != m_VehicleId' -and $nativeGate -match 'Replication.FindItemId\(m_Vehicle\)' -and $nativeGate -match 'm_Member.GetID\(\) != m_Id' -and $nativeGate -match 'm_Group.GetID\(\) != m_GroupId' -and $nativeGate -match 'GetRouteGeneration\(\) != m_iRouteGeneration' -and $nativeGate -match 'GetAssignmentRevision\(\) != m_iAssignmentRevision') 'NATIVE_GATE_FENCES_ENTITY_RPL_GROUP_ROUTE_ASSIGNMENT'
Require ($nativeGate -match 'IsAuthoritativeAIEntity\(m_Member\)' -and $nativeGate -match 'GetParentGroup\(\) == m_Group' -and $nativeGate -match 'm_Utility.m_OwnerEntity != m_Member') 'NATIVE_GATE_EXACT_AI_OWNER'
Require ((Body $nativeGate 'IsReturned') -match 'access.GetCompartment\(\) == m_Seat' -and (Body $nativeGate 'IsReturned') -match '!access.IsGettingIn\(\)' -and (Body $nativeGate 'IsReturned') -match '!access.IsGettingOut\(\)' -and (Body $nativeGate 'IsReturned') -match 'm_Seat.GetOccupant\(\) == m_Member') 'NATIVE_GATE_PHYSICAL_RETURN'
Require ((Body $nativeGate 'IsExpired') -match 'now - m_iStarted >= 60000' -and $nativeGate -notmatch 'SetOrigin|AddAction\(|\.Fail\(|\.Complete\(|SetReserved\(|CallLater\(') 'NATIVE_GATE_READ_ONLY_AND_FIXED_BOUND'
Require ((Body $transit 'ObserveNativeGate') -match 'FallbackToFoot\("NATIVE_GATE_IDENTITY_OR_DEADLINE"' -and (Body $transit 'ObserveNativeGate') -notmatch 'Record.*Progress|Record.*Motion|state.Begin\(|DeadlineMs\(') 'NATIVE_GATE_CANNOT_FABRICATE_PROGRESS_OR_REARM_BUDGET'
Require ($phaseStates -match 'm_NativeGate = null' -and (Body $transit 'AbortOwnedActions') -match 'state.SetNativeGate\(null\)') 'NATIVE_GATE_LIFECYCLE_RELEASES_OBSERVATIONS'
$route=Body $transit 'PrepareRoute'
Require ($route -match 'trip.GetVehiclePreset\(\) && state.GetRouteGeneration\(\) == 0' -and $route -match 'Wait\("PRESET_WAITING_FOR_DESTINATION"' -and $route.IndexOf('PRESET_WAITING_FOR_DESTINATION') -lt $route.IndexOf('TACTICAL_TARGET_WITHIN_DISMOUNT_RANGE')) 'INITIAL_NEARBY_PRESET_WAITS_MOUNTED_ONLY_BEFORE_FIRST_ROUTE'
Require ((Body $controller 'ApplyOutcome') -match 'outcome.GetKind\(\) == AICF_ETripOutcomeKind.WAIT && outcome.GetReason\(\) == "PRESET_WAITING_FOR_DESTINATION"' -and (Body $controller 'ExitTransit') -match 'CommitPresetDestinationWait\(false') 'CONTROLLER_OWNS_WAIT_ENTRY_AND_EXIT'
$parking=Body $trip 'CommitPresetDestinationWait'
Require ($parking -match 'Replication.IsServer' -and $parking -match 'IsVehiclePresetCurrent' -and $parking -match 'GetRouteGeneration\(\) != 0' -and $parking -match 'm_iAbsoluteDeadlineMs \+=') 'PARKING_IDENTITY_AUTHORITY_AND_PAUSED_BUDGET'
Require ((Body $trip 'IsDeadlineReached') -match 'GetPresetDestinationWaitMs\(nowMs\)' -and (Body $transit 'Tick') -match 'ProcessMandatoryCrew' -and $route -match 'InspectRouteAssetFailure') 'PARKING_KEEPS_HEALTH_CREW_AND_BOUNDED_ONWARD_ROUTE'
$exit=Body $dismount 'ProcessNormalDismount'
Require ($exit -match 'sample.m_iLogicalOccupants == 0 && sample.m_iTransitions == 0 &&\s*nowMs < state.GetTerminalDeadlineMs\(\)' -and $exit -match 'Wait\("DISEMBARK_CLEARANCE_PENDING"' -and $exit -match 'FallbackToFoot\("DISEMBARK_TIMEOUT"' -and $exit -match 'tripExitClearPolls >= TRIP_EXIT_CLEAR_POLLS') 'ON_FOOT_CLEARANCE_HAS_BOUNDED_GRACE_WITH_PHYSICAL_PROOF'
Require ($rpc -match 'RplCondition.OwnerOnly' -and $rpc -match 'RplRcver.Server' -and $rpc -match 'token <= m_iAICFVehiclePresetToken') 'OWNER_STATE_AND_REPLAY'
Require ($service -match 'ResolveVehiclePresetContext' -and $service -match 'generation != slot.GetSpawnGeneration' -and $service -match 'libraryRevision != m_Store.Revision') 'SERVER_REVALIDATION'
Require ($store -match 'version % 2|m_iVersion % 2' -and $store -match 'saved.Encode\(\) != next.Encode\(\)' -and $store -match 'm_bDeleted') 'TWO_GENERATIONS_READBACK_TOMBSTONE'
Require ($store -notmatch 'template_|SetVehiclePreset|SpawnEntity|AddSupplies') 'LIBRARY_SEPARATE_FROM_ACTIVE_AND_LEGACY'
# Отрицательные representative controls именно safety oracle.
$negative=$tick.Replace('access.GetCompartment() == seats[i]','true')
Require ($negative -notmatch 'access.GetCompartment\(\) == seats\[i\]') 'NEGATIVE_WRONG_OCCUPANT'
$negative=$key.Replace('RelativeOwnerIndex(seat)','seat.GetCompartmentMgrID()')
Require ($negative -match 'GetCompartmentMgrID' -and $negative -notmatch 'RelativeOwnerIndex') 'NEGATIVE_EPHEMERAL_SEAT'
Write-Output "PASS Vehicle preset contracts checks=$checks"
